#define main old_six
#include "six_complete.cpp"
#undef main
#include <queue>
using Bits=vector<Word>;
struct Pattern{
    int order,target,width,num;bool paired,capped=false;long long nodes,limit;Graph core{},shape{},model{};vector<Word> masks;vector<Bits> disjoint,touch;Bits all;array<int,8> choices{},classes{};
    void prepare(){width=(masks.size()+63)/64;all.assign(width,~Word(0));if(masks.size()%64)all.back()=bit(masks.size()%64)-1;disjoint.assign(masks.size(),Bits(width));touch.assign(order,Bits(width));for(int idx=0;idx<int(masks.size());++idx){for(Word rest=masks[idx];rest;rest&=rest-1)touch[low(rest)][idx/64]|=bit(idx%64);for(int other=0;other<int(masks.size());++other)if(!(masks[other]&masks[idx]))disjoint[idx][other/64]|=bit(other%64);}}
    bool bipartite()const{vector<int> color(masks.size(),-1);for(int idx=0;idx<int(color.size());++idx){if(color[idx]>=0||size_of(masks[idx])>target-3)continue;queue<int> visit;visit.push(idx);color[idx]=0;while(!visit.empty()){int here=visit.front();visit.pop();for(int block=0;block<width;++block)for(Word rest=disjoint[here][block];rest;rest&=rest-1){int there=block*64+low(rest);if(size_of(masks[there])>target-3)continue;if(color[there]==color[here])return false;if(color[there]<0){color[there]=1-color[here];visit.push(there);}}}}return true;}
    bool walk(int depth,const Graph& state){if(depth==num){model=state;return true;}Word links=shape[depth]&(bit(depth)-1);Bits alive=all;int minimum=0;for(int slot=0;slot<depth;++slot)if(classes[depth]>>slot&1)minimum=max(minimum,choices[slot]);
        for(int block=minimum/64;block<width;++block){if(block==minimum/64)alive[block]&=~Word(0)<<(minimum%64);for(Word rest=links;rest;rest&=rest-1)alive[block]&=disjoint[choices[low(rest)]][block];}
        for(int block=minimum/64;block<width;++block)while(alive[block]){int idx=64*block+low(alive[block]);alive[block]&=alive[block]-1;Word contact=masks[idx];if(size_of(contact)+size_of(shape[depth])>=target)continue;if(++nodes>limit){capped=true;return false;}int vertex=order+depth;Graph next=state;for(Word rest=contact;rest;rest&=rest-1){int old=low(rest);edge(next,old,vertex);if(paired&&(contact&bit(old^1)))next[old]&=~bit(old^1);}for(Word rest=links;rest;rest&=rest-1)edge(next,vertex,order+low(rest));
            if(Word witness=independent(next,bit(vertex+1)-1,target)){Word before=witness&(bit(order)-1),avoid=(witness&bit(vertex))?before:0,require=0;if(paired)for(Word rest=before;rest;rest&=rest-1){int old=low(rest);if((before&bit(old^1))&&(state[old]&bit(old^1)))require|=bit(old);}assert((contact&require)==require&&!(contact&avoid));for(int section=block;section<width;++section){Word remove=alive[section];for(Word rest=avoid;remove&&rest;rest&=rest-1)remove&=~touch[low(rest)][section];for(Word rest=require;remove&&rest;rest&=rest-1)remove&=touch[low(rest)][section];alive[section]&=~remove;}continue;}
            choices[depth]=idx;if(walk(depth+1,next))return true;if(capped)return false;
        }return false;}
    void orderings(){classes={};array<int,8> perm{};for(int idx=0;idx<num;++idx)perm[idx]=idx;do{bool automorphism=true;for(int left=0;left<num&&automorphism;++left)for(int right=0;right<left;++right)if(bool(shape[left]&bit(right))!=bool(shape[perm[left]]&bit(perm[right]))){automorphism=false;break;}if(!automorphism)continue;int first=0;while(first<num&&first==perm[first])++first;if(first<num){assert(perm[first]>first);classes[perm[first]]|=1<<first;}}while(next_permutation(perm.begin(),perm.begin()+num));}
};
int main(int argc,char**argv){assert(argc==2);string key;int count,paired,shapes;while(cin>>key){Pattern job;cin>>job.order>>job.target>>paired>>count;job.paired=paired;job.limit=stoll(argv[1]);for(int old=0;old<job.order;++old)cin>>job.core[old];bool open=false;if(count<0){assert(paired);Completion census(job.core,job.order,job.target,6,2000000);census.subsets(0,bit(job.order)-1);open=census.capped||census.masks.size()>5000;job.masks=move(census.masks);}else{job.masks.resize(count);for(Word& mask:job.masks)cin>>mask;}
    if(!open){sort(job.masks.begin(),job.masks.end());job.prepare();}cin>>shapes;while(shapes--){int name;cin>>name>>job.num;assert(job.num>=3&&job.num<=7);for(int idx=0;idx<job.num;++idx)cin>>job.shape[idx];string status="maskcap";job.nodes=0;job.capped=false;if(!open){if(name==700&&job.bipartite())status="bipartite";else{job.orderings();bool model=job.walk(0,job.core);status=model?"model":job.capped?"cap":"empty";}}cout<<key<<' '<<name<<' '<<status<<' '<<job.masks.size()<<' '<<job.nodes;if(status=="model"){cout<<" graph";for(int idx=0;idx<job.order+job.num;++idx)cout<<' '<<job.model[idx];}cout<<endl;}}}
